import {finite} from '../agent/core.mjs';
const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:0;
const classifier=new Set(['rules','gdn','diagnosis','event3w','esp','isolation']);
export const ROLE_NAMES={train:'训练集',validation:'验证集',test:'测试集'};
export const METRIC_INFO={MAE:['平均绝对误差','mean|预测−真实|','目标变量单位'],MSE:['均方误差','mean(预测−真实)²','目标变量单位的平方'],RMSE:['均方根误差','√MSE','目标变量单位'],R2:['决定系数','1−Σ误差²/Σ(真实−均值)²','无量纲，越接近1越好'],MAPE:['平均绝对百分比误差','mean|误差/真实|×100%','%，排除真实值接近0的样本'],sMAPE:['对称百分比误差','mean[2|误差|/(|真实|+|预测|)]×100%','%，双方都为0时记0'],Bias:['平均有符号偏差','mean(预测−真实)','目标变量单位，正值为高估'],MaxAE:['最大绝对误差','max|预测−真实|','目标变量单位'],Accuracy:['准确率','正确分类数/有标签样本数','%'],Precision:['宏平均精确率','各类别Precision的平均','%'],Recall:['宏平均召回率','各类别Recall的平均','%'],F1:['宏平均F1','各类别F1的平均','%'],AUC:['ROC曲线下面积','按异常分数排序的ROC积分','0–1；需正负样本及连续评分'],ExactMatch:['多标签完全匹配率','全部标签完全一致的样本比例','%'],HammingLoss:['标签汉明损失','标签位错误数/全部标签位数','%，越低越好'],N:['有效评价样本数','同时具备真实标签/值和预测输出的记录数','条'],LabelN:['多标签评价位数','有效样本数×标签类别数','标签位'],MAPE_N:['MAPE有效样本数','真实值绝对值大于10⁻⁸的样本数','条']};
export const PERCENT_METRICS=new Set(['Accuracy','Precision','Recall','F1','ExactMatch','HammingLoss']);
export const actualValue=(m,r)=>r.actual??r[m.target];
export function hasPrediction(m,r){return classifier.has(m.id)?r.prediction!==null&&r.prediction!==undefined&&String(r.prediction).trim()!=='':finite(r.prediction);}
const hasLabel=v=>v!==null&&v!==undefined&&String(v).trim()!=='';
function counts(labels,pairs){return labels.map(label=>{let tp=0,fp=0,fn=0,tn=0;for(const [a,p] of pairs){if(a===label&&p===label)tp++;else if(a!==label&&p===label)fp++;else if(a===label)fn++;else tn++;}const precision=tp+fp?tp/(tp+fp):0,recall=tp+fn?tp/(tp+fn):0;return {label,tp,fp,fn,tn,support:tp+fn,precision,recall,f1:precision+recall?2*precision*recall/(precision+recall):0};});}
export function roc(pairs){if(!pairs.length||!pairs.some(r=>r.y===1)||!pairs.some(r=>r.y===0))return null;const thresholds=[Infinity,...new Set(pairs.map(p=>p.score).sort((a,b)=>b-a)),-Infinity],positives=pairs.filter(p=>p.y===1).length,negatives=pairs.length-positives,curve=thresholds.map(threshold=>{const tp=pairs.filter(p=>p.y===1&&p.score>=threshold).length,fp=pairs.filter(p=>p.y===0&&p.score>=threshold).length;return {fpr:fp/negatives,tpr:tp/positives};});let auc=0;for(let i=1;i<curve.length;i++)auc+=(curve[i].fpr-curve[i-1].fpr)*(curve[i].tpr+curve[i-1].tpr)/2;return {curve,auc};}
export function summarize(m,rows,inputCount=rows.length){const kind=m.id==='diagnosis'?'multilabel':classifier.has(m.id)?'classification':'regression',out=rows.map(r=>({...r,actual:actualValue(m,r)})),predicted=out.filter(r=>hasPrediction(m,r)).length,result={kind,rows:out,inputCount,outputCount:out.length,predicted,coverage:inputCount?100*predicted/inputCount:0,metrics:null,confusion:null,perClass:[],roc:null};
 if(kind==='regression'){const pairs=out.filter(r=>finite(r.actual)&&finite(r.prediction)).map(r=>({...r,actual:Number(r.actual),prediction:Number(r.prediction),error:Number(r.prediction)-Number(r.actual)}));result.evaluated=pairs;if(!pairs.length)return result;const y=mean(pairs.map(r=>r.actual)),errors=pairs.map(r=>r.error),mse=mean(errors.map(e=>e*e)),ss=pairs.reduce((s,r)=>s+(r.actual-y)**2,0),nonzero=pairs.filter(r=>Math.abs(r.actual)>1e-8);result.metrics={MAE:mean(errors.map(Math.abs)),MSE:mse,RMSE:Math.sqrt(mse),R2:ss>1e-12?1-pairs.reduce((s,r)=>s+r.error*r.error,0)/ss:null,MAPE:nonzero.length?mean(nonzero.map(r=>Math.abs(r.error/r.actual)))*100:null,sMAPE:mean(pairs.map(r=>{const d=Math.abs(r.actual)+Math.abs(r.prediction);return d?200*Math.abs(r.error)/d:0;})),Bias:mean(errors),MaxAE:Math.max(...errors.map(Math.abs)),N:pairs.length,MAPE_N:nonzero.length};return result;}
 const pairs=out.filter(r=>hasLabel(r.actual)&&hasPrediction(m,r));result.evaluated=pairs;if(!pairs.length)return result;
 if(kind==='multilabel'){const tokens=v=>String(v).split('|').map(x=>x.trim()).filter(x=>x&&x!=='未达阈值'),labels=[...new Set(pairs.flatMap(r=>[...tokens(r.actual),...tokens(r.prediction)]))].sort();if(!labels.length)return result;const perClass=labels.map(label=>{const binary=pairs.map(r=>[tokens(r.actual).includes(label)?'1':'0',tokens(r.prediction).includes(label)?'1':'0']);return {...counts(['1'],binary)[0],label};});const exact=pairs.filter(r=>[...tokens(r.actual)].sort().join('|')===[...tokens(r.prediction)].sort().join('|')).length;result.perClass=perClass;result.metrics={ExactMatch:exact/pairs.length,Precision:mean(perClass.map(c=>c.precision)),Recall:mean(perClass.map(c=>c.recall)),F1:mean(perClass.map(c=>c.f1)),HammingLoss:perClass.reduce((s,c)=>s+c.fp+c.fn,0)/(pairs.length*labels.length),N:pairs.length,LabelN:pairs.length*labels.length};return result;}
 const normalized=pairs.map(r=>[String(r.actual),String(r.prediction)]),labels=[...new Set(normalized.flat())].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})),perClass=counts(labels,normalized),matrix=labels.map(a=>labels.map(p=>normalized.filter(([x,y])=>x===a&&y===p).length));result.perClass=perClass;result.confusion={labels,matrix};result.metrics={Accuracy:normalized.filter(([a,p])=>a===p).length/pairs.length,Precision:mean(perClass.map(c=>c.precision)),Recall:mean(perClass.map(c=>c.recall)),F1:mean(perClass.map(c=>c.f1)),N:pairs.length};if(labels.every(l=>['0','1'].includes(l))){const scored=pairs.filter(r=>finite(r.score)).map(r=>({y:Number(r.actual),score:Number(r.score)}));result.roc=roc(scored);if(result.roc)result.metrics.AUC=result.roc.auc;}return result;}
export function histogram(values,bins=10){const data=values.filter(finite).map(Number);if(!data.length)return [];let lo=Math.min(...data),hi=Math.max(...data);if(lo===hi){lo-=.5;hi+=.5;}const width=(hi-lo)/bins,out=Array.from({length:bins},(_,i)=>({left:lo+i*width,right:lo+(i+1)*width,count:0}));for(const v of data)out[Math.min(bins-1,Math.floor((v-lo)/width))].count++;return out;}
export function exportRows(summaries,source){return Object.entries(summaries).flatMap(([role,s])=>s.rows.map(r=>({...r,dataset:ROLE_NAMES[role]??role,source,error:s.kind==='regression'&&finite(r.actual)&&finite(r.prediction)?Number(r.prediction)-Number(r.actual):null,absolute_error:s.kind==='regression'&&finite(r.actual)&&finite(r.prediction)?Math.abs(Number(r.prediction)-Number(r.actual)):null})));}
export function perWellMetrics(m,rows){const ids=[...new Set(rows.map(r=>r.well_id??r.test_id??'未指定'))];return ids.map(well=>({well,...summarize(m,rows.filter(r=>(r.well_id??r.test_id??'未指定')===well)).metrics}));}
